declare(strict_types=1);require __DIR__.'/../app/bootstrap.php';require_once __DIR__.'/../app/layout.php';require_once __DIR__.'/../app/commerce_v1230.php';$u=current_user();if(!$u||!(has_permission('settings.manage',$u)||has_permission('businesses.manage',$u)||has_permission('tenants.manage',$u))){http_response_code(403);exit('Forbidden');}$msg='';$err='';try{if(($_SERVER['REQUEST_METHOD']??'')==='POST'){csrf_check();$a=(string)($_POST['action']??'');if($a==='rider'){sk1230_save_rider($_POST);$msg='Rider saved.';}elseif($a==='assign'){sk1230_assign_rider((int)($_POST['group_id']??0),(int)($_POST['rider_id']??0),(int)($u['id']??0),(int)($_POST['eta_minutes']??0));$msg='Rider assigned.';}elseif($a==='settle'){$id=(int)($_POST['settlement_id']??0);db()->prepare("UPDATE delivery_cod_settlements_v1230 SET status='settled',settled_by=?,settled_at=NOW() WHERE id=? AND tenant_id=?")->execute([(int)($u['id']??0),$id,sk1230_tid()]);$msg='COD settlement marked settled.';}}}catch(Throwable $e){$err=$e->getMessage();}$riders=sk1230_riders(false);$editRider=[];$er=(int)($_GET['edit_rider']??0);foreach($riders as $rr)if((int)$rr['id']===$er)$editRider=$rr;$groups=sk1230_admin_groups();$settlements=[];try{$q=db()->prepare('SELECT s.*,r.name rider_name,o.order_no,b.name business_name FROM delivery_cod_settlements_v1230 s LEFT JOIN delivery_riders_v1230 r ON r.id=s.rider_id LEFT JOIN commerce_order_groups_v1230 g ON g.id=s.order_group_id LEFT JOIN commerce_orders_v1230 o ON o.id=g.order_id LEFT JOIN businesses b ON b.id=g.business_id WHERE s.tenant_id=? ORDER BY s.id DESC LIMIT 200');$q->execute([sk1230_tid()]);$settlements=$q->fetchAll()?:[];}catch(Throwable $e){}$st=sk1230_admin_stats();page_start('Delivery & Riders',true);?><link rel="stylesheet" href="/assets/commerce-v1230.css?v=1230"><div class="co1230"><section class="co-top"><div><div class="co-kicker">v12.3 · HYPERLOCAL DELIVERY BACKEND</div><h1>Rider & Delivery Hub</h1><p>Register rider accounts, assign seller fulfillment groups, track delivery status and reconcile COD.</p></div><div class="co-actions"><a href="/rider-dashboard-v1230.php" target="_blank">Rider Dashboard ↗</a></div></section><?php if($msg):?><div class="notice ok"><?=sk1230_h($msg)?></div><?php endif;?><?php if($err):?><div class="notice bad"><?=sk1230_h($err)?></div><?php endif;?><section class="metrics"><div class="metric"><b><?=$st['riders']?></b><span>Active Riders</span></div><div class="metric"><b><?=count(array_filter($groups,fn($g)=>!in_array($g['status'],['delivered','cancelled'],true)))?></b><span>Open Seller Groups</span></div><div class="metric"><b><?=count(array_filter($settlements,fn($s)=>$s['status']==='pending'))?></b><span>Pending COD</span></div></section><section class="panel"><h2>Add / Update Rider</h2><p>Link the rider to an existing ShahkotPK user ID so that account can open the Rider Dashboard.</p><form method="post" class="admin-grid"><input type="hidden" name="_csrf" value="<?=sk1230_h(csrf_token())?>"><input type="hidden" name="action" value="rider"><input type="hidden" name="rider_id" value="<?=(int)($editRider['id']??0)?>"><label>User ID<input type="number" min="0" name="user_id" value="<?=sk1230_h($editRider['user_id']??'')?>"></label><label>Rider name<input required name="name" maxlength="140" value="<?=sk1230_h($editRider['name']??'')?>"></label><label>Phone<input required name="phone" maxlength="60" value="<?=sk1230_h($editRider['phone']??'')?>"></label><label>Vehicle type<input name="vehicle_type" placeholder="Bike / Car / Van" value="<?=sk1230_h($editRider['vehicle_type']??'')?>"></label><label>Vehicle no.<input name="vehicle_no" value="<?=sk1230_h($editRider['vehicle_no']??'')?>"></label><label>Zone / area<input name="zone_label" value="<?=sk1230_h($editRider['zone_label']??'')?>"></label><label class="check"><input type="checkbox" name="active" value="1" <?=!isset($editRider['active'])||!empty($editRider['active'])?'checked':''?>> Active</label><button class="btn primary"><?=$editRider?'Update Rider':'Save Rider'?></button></form><div class="table-wrap"><table class="table"><thead><tr><th>Rider</th><th>User</th><th>Vehicle</th><th>Zone</th><th>Status</th><th>Location</th></tr></thead><tbody><?php foreach($riders as $r):?><tr><td><b><?=sk1230_h($r['name'])?></b><br><?=sk1230_h($r['phone'])?></td><td>#<?=sk1230_h($r['user_id'])?></td><td><?=sk1230_h(trim($r['vehicle_type'].' '.$r['vehicle_no']))?></td><td><?=sk1230_h($r['zone_label'])?></td><td><?=sk1230_h($r['status'])?> / <?=$r['active']?'Active':'Disabled'?></td><td><?=sk1230_h($r['location_updated_at']?:'Not shared')?><br><a class="btn ghost" href="?edit_rider=<?=(int)$r['id']?>">Edit</a></td></tr><?php endforeach;?></tbody></table></div></section><section class="panel"><h2>Assign Delivery</h2><div class="table-wrap"><table class="table"><thead><tr><th>Order / Business</th><th>Total</th><th>Status</th><th>Rider</th></tr></thead><tbody><?php foreach($groups as $g):if(in_array($g['status'],['delivered','cancelled'],true))continue;?><tr><td><b><?=sk1230_h($g['order_no'])?></b><br><?=sk1230_h($g['business_name'])?><br><small><?=sk1230_h($g['customer_name'])?> · <?=sk1230_h($g['customer_phone'])?></small></td><td><?=sk1230_money($g['total'])?><br><small><?=sk1230_h($g['payment_method'])?> / <?=sk1230_h($g['payment_status'])?></small></td><td><span class="status <?=sk1230_h($g['status'])?>"><?=sk1230_h($g['status'])?></span></td><td><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?=sk1230_h(csrf_token())?>"><input type="hidden" name="action" value="assign"><input type="hidden" name="group_id" value="<?=(int)$g['id']?>"><select name="rider_id" required><option value="">Choose rider</option><?php foreach($riders as $r):if(!$r['active'])continue;?><option value="<?=(int)$r['id']?>"><?=sk1230_h($r['name'])?></option><?php endforeach;?></select><input type="number" name="eta_minutes" min="0" max="600" placeholder="ETA min"><button class="btn blue wide">Assign / Reassign</button></form></td></tr><?php endforeach;?></tbody></table></div></section><section class="panel"><h2>COD Settlements</h2><p>Rider cash collection is recorded per seller group. Mark settled only after physical/account reconciliation.</p><div class="table-wrap"><table class="table"><thead><tr><th>Order</th><th>Rider</th><th>Business</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($settlements as $s):?><tr><td><?=sk1230_h($s['order_no'])?></td><td><?=sk1230_h($s['rider_name'])?></td><td><?=sk1230_h($s['business_name'])?></td><td><?=sk1230_money($s['amount'])?></td><td><?=sk1230_h($s['status'])?></td><td><?php if($s['status']!=='settled'):?><form method="post"><input type="hidden" name="_csrf" value="<?=sk1230_h(csrf_token())?>"><input type="hidden" name="action" value="settle"><input type="hidden" name="settlement_id" value="<?=(int)$s['id']?>"><button class="btn ghost">Mark Settled</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section></div><?php require __DIR__.'/../app/end.php';?>
